<?php
namespace App\Http\Controllers;
use App\Models\Alats; use App\Models\Kategoris; use Illuminate\Http\Request; use Illuminate\Database\QueryException;
class AlatsController extends Controller { public function index(){return view('alats.index',['alats'=>Alats::with('kategori')->latest()->paginate(15)]);} public function create(){return view('alats.form',['kategoris'=>Kategoris::orderBy('nama_kategori')->get()]);} public function store(Request $r){Alats::create($r->validate(['kategori_id'=>'required|exists:kategoris,id','nama_alat'=>'required|string|max:255','stok'=>'required|integer|min:0']));return redirect()->route('alats.index')->with('sukses','Alat berhasil ditambahkan.');} public function show(Alats $alat){return redirect()->route('alats.edit',$alat);} public function edit(Alats $alat){return view('alats.form',['alat'=>$alat,'kategoris'=>Kategoris::orderBy('nama_kategori')->get()]);} public function update(Request $r,Alats $alat){$alat->update($r->validate(['kategori_id'=>'required|exists:kategoris,id','nama_alat'=>'required|string|max:255','stok'=>'required|integer|min:0']));return redirect()->route('alats.index')->with('sukses','Data alat diperbarui.');} public function destroy(Alats $alat){try{$alat->delete();}catch(QueryException $e){return back()->with('error','Alat masih tercatat dalam transaksi peminjaman.');}return redirect()->route('alats.index')->with('sukses','Alat dihapus.');} }
